#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64_t n, m, k;
    cin >> n >> m >> k;

    if (n == m) {
        cout << 1 << '\n';
        return 0;
    }

    int64_t curr = 2;
    m -= n;
    m -= 1;

    int64_t l = max<int64_t>(k - 1, 1);
    int64_t r = min<int64_t>(n, k + 1);

    while (!(l == 1 && r == n)) {
        if (m < r - l + 1) {
            cout << curr << '\n';
            return 0;
        }

        m -= r - l + 1;
        ++curr;
        l = max<int64_t>(l - 1, 1);
        r = min<int64_t>(r + 1, n);
    }

    curr += m / n;
    cout << curr << '\n';

    return 0;
}

#include <bits/stdc++.h>
#define IN(a,b) (a.find(b) != a.end())
#define p(a,b) make_pair(a,b)
