std::ostream& operator<<(std::ostream& os, const std::pair<A, B>& c) {
    os << "(" << c.first << ", " << c.second << ")";
    return os;
}

template<typename T>
std::ostream& operator<<(std::ostream& os, const std::vector<T>& c) {
    if (c.empty()) {
        os << "{}";
        return os;
    }
    os << "{" << c[0];
    for (int64_t i = 1; i < (int64_t)c.size(); i++) {
        os << ", " << c[i];
    }
    os << "}";
    return os;
}

